<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientJwksUriAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientJwksUriAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientJwksUriAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getJwksUri returns null on a freshly created holder.
     */
    public function testJwksUriNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientJwksUriAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isJwksUriAssigned());
        $this->assertNull($holder->getJwksUri());
    }
}
class ImplWithTrustedClientJwksUriAttributeHolderUnitTest
{
    use TrustedClientJwksUriAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedJwksUriRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultJwksUri();
    }
}
